import{_ as t,h as o,i as e,c as i,v as r,p as A,x as l,m as p,e as d,S as s}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"Arena-Hard / AlpacaEval 2","description":"","frontmatter":{"title":"Arena-Hard / AlpacaEval 2","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/arena-hard.md","filePath":"llm/arena-hard.md","lastUpdated":1788454257000}'),E={name:"llm/arena-hard.md"};function h(c,a,m,u,B,_){const n=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="arena-hard-alpacaeval-2" tabindex="-1">Arena-Hard / AlpacaEval 2 <a class="header-anchor" href="#arena-hard-alpacaeval-2" aria-label="Permalink to &quot;Arena-Hard / AlpacaEval 2&quot;">​</a></h1><div class="epigraph"><p>真人 Arena 的 Elo 贵、慢、提示不可复现；用一套从线上筛出的难题，让强模型当法官做成对比较，并控制长度，可以得到与人类榜相关、却能每周重跑的代理指标。</p><footer>—— Li et al., Arena-Hard；Dubois et al., Length-Controlled AlpacaEval</footer></div><p><a href="/llm/lmsys-arena">LMSYS Arena</a> 直接测人更想用谁，但投票要积累、提示分布会漂、闭源模型上新要等。实验室需要一个能对着同一批题反复跑的近似。Li 等人的 Arena-Hard（及自动评测管线 Arena-Hard-Auto）从 Arena 日志里筛「更难、区分度更高」的提示，用 GPT-4 一类模型当法官，对候选与固定基线做成对判决，得到与人类 Arena 名次高相关的胜率。Dubois 等人的 AlpacaEval 2 用约八百条指令、同样 LLM 法官，并显式做<strong>长度控制</strong>（LC win rate），纠正「更长更容易赢」的偏差。两套都是 LLM-as-judge 的成对代理，不是知识闭卷考，也不是 <a href="/llm/mt-bench">MT-Bench</a> 那种绝对 1–10 分。本篇写题怎么筛、法官偏差怎么补、以及代理榜不能替代真人票。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态能力榜饱和之后，产品差距更多落在文风、拒答、指令服从和长回答是否真有用。这些很难用精确匹配打分。Arena 能打，但工程师不能每次改系统提示都等一万票。朴素的自动替代——让 GPT-4 给回答打 1 到 10——会撞上绝对评分的校准问题，见 <a href="/llm/absolute-rating-prefs">Likert 与绝对评分</a>。成对「A 还是 B」更稳，但仍有位置偏差、自我增强（法官偏爱同家族腔）、以及冗长度偏差。</p><p>题也不能太随便。Alpaca 早期那批过短、过易的指令，强模型之间分不开。需要从真实用户提示里挑出「足够难、足够多样、模型之间会打架」的子集，否则代理榜会在满分附近抖动。Arena-Hard 的「Hard」指的是区分力，不是奥数。</p><h3 id="与人类-arena-相关-不等于测同一个量" tabindex="-1">与人类 Arena 相关，不等于测同一个量 <a class="header-anchor" href="#与人类-arena-相关-不等于测同一个量" aria-label="Permalink to &quot;与人类 Arena 相关，不等于测同一个量&quot;">​</a></h3><p>相关高，说明法官在这批题上的偏好序接近投票者的偏好序。提示分布一旦离开 Arena 用户（例如全是内部客服话术），相关可以掉。风格控制实验（截断到相近长度再判）若让名次洗牌，原相关里有相当一部分是在奖长度。因此「与 Arena Spearman 高」是该协议、该题集、该法官上的性质，必须随三者一起引用。</p><p><span class="marginnote">法官模型一换代，分数尺度和偏好都会动。Arena-Hard / AlpacaEval 的数字只能在冻结的法官版本内比。换 GPT-4o 当法官之后，不要和论文里 GPT-4-0314 的表直接减。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Arena-Hard-Auto 的典型协议：约五百条从 Arena 聚类、过滤后的难题；候选模型与基线（如 GPT-4-0314）对同一提示各生成一条；法官看一对、输出胜者；聚合为对基线的胜率，有时再映射到类似 Arena 的分数。提示筛选要去掉过短、过危险、或几乎所有模型都答好的题，否则方差全是噪声。生成侧的温度、长度上限应接近 Arena 的产品设定，否则代理的是另一套解码。</p><p>AlpacaEval 2 用固定的 805 条指令（来自 AlpacaEval 源头），法官同样成对，对照一个参考模型。Dubois 等人的长度控制把「因更长而赢」的部分回归掉，报告 LC 胜率。应同时报原始胜率与 LC：两者差距大，说明在刷长度；差距小，说明赢在内容或其它风格维。不要只报对自己有利的那一列。</p> \\[\\mathrm{WR}=\\frac{n_{\\mathrm{win}}+\\tfrac12 n_{\\mathrm{tie}}}{n_{\\mathrm{win}}+n_{\\mathrm{lose}}+n_{\\mathrm{tie}}} \\]<p>LC 则在此之上对长度做调整（论文中的回归 / 再加权）。平局处理、位置对换（A/B 各判一次）必须写进脚本：只跑一个方向会把位置偏差写进胜率。</p><h3 id="风格控制不是可选项" tabindex="-1">风格控制不是可选项 <a class="header-anchor" href="#风格控制不是可选项" aria-label="Permalink to &quot;风格控制不是可选项&quot;">​</a></h3><p>长度、列表、emoji、套话道歉，都是 LLM 法官与人类投票者的共同弱点。Arena-Hard 后续工作加入风格控制特征；AlpacaEval 2 把长度提到一等指标。内部复现至少要做：原回答、截断到基线相近词数、去 markdown。三列名次若剧烈跳动，对外只报原胜率就是在发风格榜。这与真人 Arena 的长度控制实验是同一逻辑。</p>',16)),(e(),A(s,null,{default:l(()=>[d(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%AD%9B%E9%80%89%E5%90%8E%E7%9A%84%E9%9A%BE%E9%A2%98%20%2F%20805%20%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20G%5B%22%E5%80%99%E9%80%89%E4%B8%8E%E5%9F%BA%E7%BA%BF%E7%94%9F%E6%88%90%22%5D%0A%20%20G%20--%3E%20J%5B%22LLM%20%E6%B3%95%E5%AE%98%E6%88%90%E5%AF%B9%E5%88%A4%E5%86%B3%22%5D%0A%20%20J%20--%3E%20WR%5B%22%E5%8E%9F%E5%A7%8B%E8%83%9C%E7%8E%87%22%5D%0A%20%20J%20--%3E%20LC%5B%22%E9%95%BF%E5%BA%A6%E6%8E%A7%E5%88%B6%E8%83%9C%E7%8E%87%22%5D%0A%20%20WR%20--%3E%20COR%5B%22%E4%B8%8E%E4%BA%BA%E7%B1%BB%20Arena%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20LC%20--%3E%20COR%0A%20%20POS%5B%22A%2FB%20%E5%AF%B9%E6%8D%A2%22%5D%20--%3E%20J%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LLM 法官近似的是「哪条读起来更像好助手」，特征来自它自己的对齐：有结构、有步骤、语气稳、少明显错误。它不自动检查代码是否能跑、事实是否新、政策是否违规——除非提示里把这些写成评分规则，且法官真的执行。因此代理榜会系统性抬高「看起来勤快」的模型，压低「短而正确」的模型；LC 只修正勤快里的长度分量，修正不了列表癖和套话。</p><p>题的难度机制也不同。Arena-Hard 来自真人已经打过的硬提示，长尾、脏、带真实意图；AlpacaEval 的 805 更干净、更像早期指令微调分布。前者更接近 Arena 相关，后者更便宜、更稳、更易被指令数据污染。两套一起看：AlpacaEval LC 高而 Arena-Hard 低，可能是在老指令分布上过拟合；反过来，可能更适应线上难题、不适应 Alpaca 腔。</p><h3 id="自我增强与家族腔" tabindex="-1">自我增强与家族腔 <a class="header-anchor" href="#自我增强与家族腔" aria-label="Permalink to &quot;自我增强与家族腔&quot;">​</a></h3><p>法官若与候选同家族，可能偏爱相似的拒答模板、相似的代码块风格。盲的是名字，不是文风水印。缓解包括：用与候选无关的法官、多法官投票、以及在报告里标明法官身份。不能消除。这是所有 LLM-as-judge 成对协议的结构缺陷，不是 Arena-Hard 独有，见 <a href="/llm/pairwise-label-protocol">成对比较协议</a>。</p><p><span class="marginnote">相关是序的相关。两个模型在代理榜上差 2 个胜率点，在真人 Arena 上可能分不开，也可能差半档 Elo。不要把代理胜率差直接翻译成「用户会多喜欢百分之几」。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>两套都不测工具、多轮长会话、或私有知识。难提示仍以英语、技术、写作类为多，中文产品要换中文题与中文法官，相关必须重新测，不能借用英文 Spearman。安全题若被筛掉，代理榜会鼓励更敢答的模型，与内部安全门禁冲突——应另跑安全集，不要把 Arena-Hard 当有害性证书。</p><p>污染：805 条和 500 条都会进下一轮爬虫与合成数据。动态补充新难题、保留私有平行集，与静态基准相同。法官费用随对数线性涨；可用更小法官做 CI、用论文指定法官做发布，但两套分数不可混写进同一列。</p><p>不要用这两张表替代 <a href="/llm/mmlu">MMLU</a>、数学与代码。代理的是聊天偏好序。一个 Arena-Hard 很高、GSM8K 很低的模型，可能是讨好型助手，不是通才。</p><p><span class="marginnote">基线模型必须冻结。对照「当时最强的内部 checkpoint」而不是论文指定的 GPT-4-0314，胜率无法与文献比。内部纵向比较可以另选基线，对外引用不行。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Arena-Hard 用线上筛出的难题和 LLM 成对法官近似人类 Arena；AlpacaEval 2 用 805 条指令并报告长度控制胜率。</li><li>原始胜率与 LC、截断、去格式三列都应看；只报一列会把风格当成能力。</li><li>与 Arena 的相关绑定于题、法官版本和生成协议，换任一者要重测。</li><li>自我增强、位置偏差、英语偏置和污染是结构限制。</li><li>它们不替代真人票、也不替代知识 / 数学 / 工具评测。</li><li>出处：Li et al., Arena-Hard；Dubois et al., <em>Length-Controlled AlpacaEval</em>；人类榜见 LMSYS Chatbot Arena；成对骨架见 Zheng 等 LLM-as-judge 工作。</li></ul>',13))])}const b=t(E,[["render",h]]);export{f as __pageData,b as default};
